:root {
  --paper: #fffdf8;
  --ink: #26352f;
  --muted: #6d786f;
  --line: #d9ddd1;
  --sage: #e4ebd8;
  --moss: #4f6c53;
  --clay: #c86643;
  --warm: #f4dfbd;
}

.firing-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background-color: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
}

.title-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow,
.stage-label,
.program-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
  font-weight: 700;
}

.status {
  padding: 5px 9px;
  color: var(--moss);
  background-color: var(--sage);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.program {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  background-color: var(--warm);
  border-radius: 10px;
}

.program-value {
  font-size: 12px;
  letter-spacing: 0.03em;
}

.date {
  margin-left: auto;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.curve-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 12px 0;
}

.stage {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 11px;
  background-color: var(--sage);
  border-radius: 11px;
}

.stage:nth-child(2) {
  background-color: var(--warm);
}

.stage:nth-child(3) {
  background-color: var(--paper);
  border: 1px solid var(--line);
}

.stage-temp {
  color: var(--clay);
  font-size: 23px;
  line-height: 1;
}

.stage-note {
  color: var(--muted);
  font-size: 12px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-note {
  color: var(--muted);
  font-size: 12px;
}

button {
  padding: 7px 12px;
  color: var(--paper);
  background-color: var(--moss);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}
